using Lumoin.Veritas.Geo.SimpleFeatures;

namespace Lumoin.Veritas.Tests.Geo;

/// <summary>
/// The pinned clearance outcome of every CITE KML corpus artifact — the test face of the corpus
/// ledger the exhaustive-clearance ruling requires (the prose ledger lives in
/// <c>Geo/CiteKmlCorpus/PROVENANCE.md</c>). Every vendored artifact has exactly
/// one recorded outcome: a parse whose kind, emptiness, and canonical text digest are pinned, or
/// a refusal whose kind and byte anchor are pinned. Unlike the GML corpus no coordinate-reference
/// face exists — KML fixes CRS84 longitude-latitude by definition and the reader returns no
/// system — and an accepted artifact pins its POST-collapse kind: a MultiGeometry input pins
/// GeometryCollection and a LinearRing input pins LineString. Regenerating an entry is a
/// deliberate contract-change event, never a test-time convenience.
/// </summary>
internal static class CiteKmlCorpusExpectations
{
    /// <summary>One pinned clearance outcome. Exactly one of the two faces is meaningful per row.</summary>
    internal readonly record struct CorpusExpectation(
        bool Accepts,
        GeometryKind GeometryKind,
        bool IsEmpty,
        string WktSha256,
        GeometryCodecRefusalKind RefusalKind,
        int RefusalByteOffset);

